before_hook() {
  # Runs after argument parsing and filters, before any command

  if [[ ${args[--verbose]} ]]; then
      export VERBOSE=true
      export REDIRECT=/dev/stdout
  fi

}

initialize() {
  declare -g version="2.0.0"

  # Runs before argument parsing, for every command (including --help)

  # Everything is relative to the script location, never to the current directory
  BASE_DIR=$(cd "$(dirname "$(realpath "${BASH_SOURCE[0]}")")" && pwd)

  # Values computed by init (domain, credentials, tokens...) and the paths
  load_env_file

  export COMPOSE_PROJECT_NAME="competition_scripts"
  export COMPOSE_IGNORE_ORPHANS=true

  export VERBOSE=false
  export REDIRECT=/dev/null

  # Services (see src/lib/services.sh), loaded at runtime: hooks in service.sh, helpers in lib/*.sh.
  # Adding or changing a service needs no regeneration.
  for service_file in "$SERVICES_DIR"/*/service.sh "$SERVICES_DIR"/*/lib/*.sh; do
      # shellcheck disable=SC1090
      [ -f "$service_file" ] && source "$service_file"
  done

}

run() {

  declare -g long_usage=''
  declare -g -A args=()
  declare -g -A deps=()
  declare -g -a env_var_names=()
  declare -g -a input=()

  normalize_input "$@"
  parse_requirements "${input[@]}"
  before_hook

  case "$action" in
    "setup") competition.sh_setup_command ;;
    "check-config") competition.sh_check_config_command ;;
    "init") competition.sh_init_command ;;
    "start") competition.sh_start_command ;;
    "stop") competition.sh_stop_command ;;
    "recreate") competition.sh_recreate_command ;;
    "import-frameworks") competition.sh_import_frameworks_command ;;
    "prefetch-npm") competition.sh_prefetch_npm_command ;;
    "npm-proxy") competition.sh_npm_proxy_command ;;
    "deploy-apis") competition.sh_deploy_apis_command ;;
    "reset-api") competition.sh_reset_api_command ;;
    "backup") competition.sh_backup_command ;;
    "restore") competition.sh_restore_command ;;
    "clean") competition.sh_clean_command ;;
  esac
}

start() {
  command_line_args=("$@")
  initialize
  run "${command_line_args[@]}"
}

start "$@"
